"id": "QueryDateRange",
"description": "An object defining a range for a date value to be used in queries.",
"choices": [
  {
    "type": "object",
    "properties": {
      "recent": {
        "type": "boolean",
        "description": "Whether the date must be considered to be recent by Thunderbird (within the last month) or not, to match the query."
      }
    }
  },
  {
    "type": "object",
    "properties": {
      "after": {
        "$ref": "extensionTypes.Date",
        "optional": true,
        "description": "The minimum date required to match the query."
      },
      "before": {
        "$ref": "extensionTypes.Date",
        "optional": true,
        "description": "The maximum date required to match the query."
      }
    }
  }
]
